    Bug 1948678 - Follow-up, fix perf regression in nsMailboxUrl::GetMessageHeader. r=mkmelin


    When opening an .EML file, `nsMailboxUrl::GetMessageHeader` was called not only in `nsMailboxProtocol::Initialize`, but also in `getMsgHdrForCurrentURL` from `mimei.cpp` and `nsMsgStatusFeedback::OnStateChange`. Since https://phabricator.services.mozilla.com/D238540 only addresses the first of these three instances, `nsMailboxUrl::GetMessageHeader` itself should also be exited early to avoid traversing all folders searching for a database that doesn't exist for .EML files.

    Differential Revision: https://phabricator.services.mozilla.com/D238953

diff --git a/mailnews/local/src/nsMailboxProtocol.cpp b/mailnews/local/src/nsMailboxProtocol.cpp
index 442f7523a42..8c6605737b1 100644
--- a/mailnews/local/src/nsMailboxProtocol.cpp
+++ b/mailnews/local/src/nsMailboxProtocol.cpp
@@ -74,11 +74,7 @@ nsresult nsMailboxProtocol::Initialize(nsIURI* aURL) {
       nsMsgKey msgKey;
       m_runningUrl->GetMessageKey(&msgKey);
       if (msgKey == 0) {
-        // This appears to be an .eml file. Be sure not to call
-        // nsMailboxUrl::GetMessageHeader in this case, as it would
-        // loop through all folders unsuccessfully looking for a database
-        // with a matching file path, with potentially huge performance
-        // implications.
+        // This appears to be an .eml file.
         rv = OpenFileSocket(aURL);
       } else {
         nsCOMPtr<nsIMsgMessageUrl> msgUrl =
diff --git a/mailnews/local/src/nsMailboxUrl.cpp b/mailnews/local/src/nsMailboxUrl.cpp
index 0b12cb20d1f..7d94991d7c6 100644
--- a/mailnews/local/src/nsMailboxUrl.cpp
+++ b/mailnews/local/src/nsMailboxUrl.cpp
@@ -209,6 +209,13 @@ nsresult nsMailboxUrl::GetMsgHdrForKey(nsMsgKey msgKey, nsIMsgDBHdr** msgHdr) {
   NS_ENSURE_ARG_POINTER(msgHdr);
   NS_ENSURE_TRUE(m_filePath, NS_ERROR_NULL_POINTER);

+  if (msgKey == 0) {
+    // This appears to be an .eml file. Just return without error instead of
+    // looping through all folders unsuccessfully looking for a database with
+    // a matching file path, with potentially huge performance implications.
+    return NS_OK;
+  }
+
   nsresult rv;
   nsCOMPtr<nsIMsgDatabase> mailDB;
   nsCOMPtr<nsIMsgDBService> msgDBService =
@@ -255,8 +262,7 @@ nsresult nsMailboxUrl::GetMsgHdrForKey(nsMsgKey msgKey, nsIMsgDBHdr** msgHdr) {
     return mailDB->GetMsgHdrForKey(msgKey, msgHdr);
   }

-  // This may be an .eml file.
-  return NS_OK;
+  return NS_ERROR_UNEXPECTED;
 }

 NS_IMETHODIMP nsMailboxUrl::GetMessageHeader(nsIMsgDBHdr** aMsgHdr) {
